// Initialize random seed
std::srand(std::time(nullptr));

// Count intersections
int intersections = 0;

// Cast multiple rays in random directions
for (int i = 0; i < numberOfChecks; i++) {
    // Generate random direction vector
    double x = (std::rand() / (double)RAND_MAX) * 2.0 - 1.0;
    double y = (std::rand() / (double)RAND_MAX) * 2.0 - 1.0;
    double z = (std::rand() / (double)RAND_MAX) * 2.0 - 1.0;

    // Normalize the direction vector
    double length = std::sqrt(x*x + y*y + z*z);
    if (length < 1e-10) continue; // Skip zero vectors
    x /= length;
    y /= length;
    z /= length;

    // Create ray starting from point p in the random direction
    CGALRay ray(CGALPoint(p.x(), p.y(), p.z()), CGALPoint(p.x() + x, p.y() + y, p.z() + z));

    // Count intersections with triangles
    std::list<CGALTrianglePrimitive> intersected_primitives;
    tree.intersect_ray(ray, std::back_inserter(intersected_primitives));

    // Count odd intersections (point is inside if odd number of intersections)
    intersections += intersected_primitives.size();
}

// Point is inside if odd number of intersections
return (intersections % 2) == 1;

